import React, { useEffect, useState } from 'react';

import PageLoader from '@components/PageLoader';
import { err } from '@helpers/notificationHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohImagePlaceholder from '@ui-kit/ImagePlaceholder';

import { getBackpacks } from '../../@services/equip.service';
import { IBackpack } from '../../@types/equip.types';
import { addBackpackAsync } from '../BackpackEditor/backpackEditorHelper';

interface IBackpackSelectorProps {
  onSelect: (bp: IBackpack) => void;
}

const BackpackSelector: React.FC<IBackpackSelectorProps> = ({ onSelect }) => {
  const [backpacks, setBackpacks] = useState<IBackpack[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    getBackpacks()
      .then(setBackpacks)
      .catch(err)
      .finally(() => setIsLoading(false));
  }, []);

  if (isLoading) {
    return <PageLoader />;
  }
  const handleAdd = () => {
    addBackpackAsync().then(onSelect);
  };

  if (!backpacks.length) {
    return (
      <Empty>
        <aside className="text-center">
          <p>
            Похоже вы делаете это впервые :) <br />
            Вам нужно добавить рюкзак в который вы будете складывать свое походное снаряжение <br />
            Не забудьте указать вес пустого рюкзака и его вместимость (объём)
          </p>
          <PohButton size={ButtonSize.Big} variant={ButtonVariant.Primary} onClick={handleAdd}>
            Добавить рюкзак
          </PohButton>
        </aside>
      </Empty>
    );
  }

  return (
    <section>
      <h4>
        Выбрать рюкзак для похода
        <PohButton className="float-end" size={ButtonSize.Small} onClick={handleAdd}>
          Добавить новый
        </PohButton>
      </h4>
      <div style={{ overflowX: 'auto' }}>
        <div className="d-flex justify-content-center">
          {backpacks.map((backpack) => (
            <PohCard
              title={backpack.name}
              key={backpack.id}
              className="mx-1"
              bodyClassName=" d-flex justify-content-between flex-column"
              style={{ maxWidth: 220, minWidth: 220 }}
            >
              <div className="mt-auto" />
              <PohImagePlaceholder
                src={backpack.photo}
                width="100%"
                alt={backpack.name}
                iconName={IconsEnum.backpack}
              />
              <p>
                <PohBadge className="me-1" variant={BadgeVariant.Warning}>
                  {backpack.weight}&thinsp;кг.
                </PohBadge>
                <PohBadge variant={BadgeVariant.Warning}>{backpack.value}&thinsp;л.</PohBadge>
              </p>
              <PohButton className="w-100" onClick={() => onSelect(backpack)}>
                Выбрать
              </PohButton>
            </PohCard>
          ))}
        </div>
      </div>
    </section>
  );
};

export default BackpackSelector;
