import React from 'react';

import { showModal } from '@ui-kit/Modal';

import BackpackSelectModal from './components/BackpackSelectModal';
import { IBackpack } from '../../@types/equip.types';

export function selectBackpackAsync(): Promise<IBackpack> {
  return new Promise((resolve) => {
    showModal({
      title: 'Выбор рюкзака',
      size: 'sm',
      children: (closeHandler: () => void) => (
        <BackpackSelectModal
          onSelect={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}

export default { selectBackpackAsync };
